mapper.update:
UPDATE public_recipes pr
SET average_rating = COALESCE((
        SELECT ROUND(AVG(score), 1)
        FROM recipe_ratings
        WHERE public_recipe_id = #{publicRecipeId}
    ), 0),
    rating_count = (
        SELECT COUNT(*)
        FROM recipe_ratings
        WHERE public_recipe_id = #{publicRecipeId}
    ),
    tried_count = (
        SELECT COUNT(*)
        FROM recipe_try_records
        WHERE public_recipe_id = #{publicRecipeId}
    ),
    favorite_count = (
        SELECT COUNT(*)
        FROM recipe_favorites
        WHERE public_recipe_id = #{publicRecipeId}
    ),
    hot_score = (
        COALESCE((SELECT ROUND(AVG(score), 1) FROM recipe_ratings WHERE public_recipe_id = #{publicRecipeId}), 0) * 40
        + (SELECT COUNT(*) FROM recipe_ratings WHERE public_recipe_id = #{publicRecipeId}) * 2
        + (SELECT COUNT(*) FROM recipe_try_records WHERE public_recipe_id = #{publicRecipeId}) * 1.5
        + (SELECT COUNT(*) FROM recipe_favorites WHERE public_recipe_id = #{publicRecipeId}) * 2
        + pr.fork_count * 2
    ),
    updated_at = NOW()
WHERE pr.id = #{publicRecipeId}
